def _hi(t):
    return ' lang="hi"' if any('\u0900' <= c <= '\u097f' for c in t) else ''

def section(title, text, id='', tint=False):
    cls = 'journey-section tint' if tint else 'journey-section'
    hi = _hi(title)
    return f'<section class="{cls}"{(" id=" + chr(34) + id + chr(34)) if id else ""}{hi}><div class="container reading-width"><h2>{title}</h2>{text}</div></section>'

def photo(src, w, h, alt, cap):
    return f'<figure class="clinic-photo"><img src="{src}" width="{w}" height="{h}" loading="lazy" alt="{e(alt, quote=True)}"><figcaption>{e(cap)}</figcaption></figure>'

def faq_block(faqs):
    items = ''.join(f'<details{_hi(q)}><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q, a in faqs)
    return f'<section class="journey-section" id="page-faq"><div class="container reading-width"><h2>Frequently asked questions</h2><div class="journey-faq">{items}</div></div></section>'

