def about_body():
    cards = ''.join(f'<article class="journey-card"><h3>{e(t)}</h3><ul class="journey-list">' + ''.join(f'<li>{e(i)}</li>' for i in items) + '</ul></article>' for t, items in ABOUT_EXPERIENCE)
    return (
     '<section class="journey-section"><div class="container journey-split"><div><p class="journey-name">MBBS · MS General Surgery (PGIMER Chandigarh) · FMAS · FIAGES · FALS (Robotic)</p><p>Dr. Vikeerna Bharti is a consultant general and laparoscopic surgeon in Ranchi, Jharkhand. He holds an MS in General Surgery from PGIMER Chandigarh, completed senior residency at PGIMER and AIIMS Bhubaneswar, and now practises at Samford Super Speciality Hospital, Ranchi, with a morning and evening OPD at Ranchi Dental and Polyclinic, Bariatu, and a visiting OPD at Sai Sushila Sishu Hospital, Garhwa.</p><p>His practice covers advanced laparoscopic and gastrointestinal surgery, emergency and trauma surgery, abdominal wall reconstruction, bariatric and metabolic surgery, breast and endocrine surgery, and vein treatment including radiofrequency ablation.</p><div class="journey-actions"><a class="journey-button" href="appointments.html#request">Book an OPD consultation</a><a class="journey-button secondary" href="second-opinion-surgery-ranchi.html">Get a second opinion</a></div></div>'
     '<figure class="journey-portrait"><img src="images/dr-vikeerna-bharti-portrait.jpg" width="1021" height="1280" alt="Dr. Vikeerna Bharti, general and laparoscopic surgeon in Ranchi"></figure></div></section>'
     '<section class="journey-section tint" id="training"><div class="container"><h2>Qualifications and clinical experience</h2><div class="journey-grid">'
     '<article class="journey-card"><h3>Education &amp; fellowships</h3><ul class="journey-list"><li><strong>MS General Surgery</strong><br>PGIMER Chandigarh</li><li><strong>MBBS</strong><br>Amrita Institute of Medical Sciences, Kochi</li><li><strong>FMAS</strong><br>Fellowship in Minimal Access Surgery (AMASI)</li><li><strong>FIAGES</strong><br>Fellowship of the Indian Association of Gastrointestinal Endosurgeons</li><li><strong>FALS (Robotic)</strong><br>Fellowship of Advanced Laparoscopic Surgery (Robotic), Indian Association of Gastrointestinal Endo Surgeons (IAGES)</li></ul></article>'
     '<article class="journey-card"><h3>Clinical experience</h3><ul class="journey-list"><li><strong>Samford Super Speciality Hospital, Ranchi</strong><br>Consultant General &amp; Laparoscopic Surgeon (current)</li><li><strong>Paras HEC Hospital, Ranchi</strong><br>Consultant General Surgeon</li><li><strong>AIIMS Bhubaneswar</strong><br>Senior Resident, General Surgery</li><li><strong>PGIMER Chandigarh</strong><br>Senior Resident, General Surgery</li></ul></article>'
     '<article class="journey-card"><h3>Teaching and research</h3><ul class="journey-list"><li>Taught and supervised MBBS students, interns and junior residents at PGIMER and AIIMS Bhubaneswar</li><li>Collaborator, GlobalSurg study in The Lancet Global Health</li><li>Co-author, “Prolapse Rectum”, Springer book chapter</li><li>Published hernia research on eTEP and primary lumbar hernia</li></ul><a class="journey-textlink" href="blog.html">All publications →</a></article>'
     '</div></div></section>'
     f'<section class="journey-section" id="experience"><div class="container"><h2>Operative experience</h2><p class="section-intro">From Dr. Bharti’s September 2026 CV. The right operation for an individual patient is decided after assessment.</p><div class="journey-grid">{cards}</div><div class="photo-row ot-row">'+''.join(photo(src,1050,1400,alt,alt) for src,alt in [('images/ot-laparoscopy-dr-bharti-1.jpg','Dr. Vikeerna Bharti during laparoscopic surgery'),('images/ot-surgical-team.jpg','With the operating theatre team'),('images/ot-laparoscopy-dr-bharti-2.jpg','Keyhole surgery in progress')])+'</div></div></section>'
     '<section class="journey-section tint"><div class="container"><h2>Where to meet Dr. Bharti</h2><div class="photo-row">' + ''.join(photo(*p) for p in CLINIC_PHOTOS) + '</div><div class="journey-actions"><a class="journey-button" href="appointments.html#locations">Clinics &amp; OPD timings</a><a class="journey-button secondary" href="gallery.html">View the gallery</a></div></div></section>')

def gallery_body():
    groups = [('theatre', 'In the operating theatre'), ('milestones', 'Professional milestones'), ('news', 'In the news and in the community')]
    out = []
    for key, title in groups:
        figs = ''.join(f'<figure><a href="{full}" target="_blank" rel="noopener"><img src="{thumb}" width="560" height="420" loading="lazy" alt="{e(alt, quote=True)}"></a><figcaption>{e(cap)}</figcaption></figure>' for full, thumb, alt, cap, g in GALLERY if g == key)
        out.append(f'<section class="journey-section{" tint" if key == "milestones" else ""}" id="{key}"><div class="container"><h2>{title}</h2><div class="gallery-grid">{figs}</div></div></section>')
    clinics = '<section class="journey-section" id="clinics"><div class="container"><h2>Our clinics and hospital facilities</h2><div class="photo-row">' + ''.join(photo(*p) for p in CLINIC_PHOTOS + GARHWA_PHOTOS) + '</div></div></section>'
    note = '<div class="container"><p class="journey-small">Photographs that include patients are shared with their written consent. Newspaper reports are shown as published and describe past events; they do not predict an individual patient’s result.</p></div>'
    return ''.join(out[:2]) + clinics + out[2] + note
